def total(items):
    t = 0
    for item in items:
        t += item.price * item.quantity
    return t


def apply_discount(total_amount, percent):
    return total_amount - total_amount * percent


def checkout(cart, discount_percent):
    return apply_discount(total(cart.items), discount_percent)

